+            while (const char* name = g_dir_read_name(dir)) {
+                GUniquePtr<char> child(g_build_filename(m_path.get(), name, nullptr));
+                g_unlink(child.get());
+            }
+            g_dir_close(dir);
+        }
+        g_rmdir(m_path.get());
+    }
+
+    const char* path() const { return m_path.get(); }
+    bool isValid() const { return !!m_path; }
