+        RefPtr frame = WebFrameProxy::webFrame(frameIdentifier);
+        if (!frame)
+            continue;
+
+        processFrames.ensure(protect(frame->process()), [] {
+            return Vector<FrameIdentifier> { };
+        }).iterator->value.append(frameIdentifier);
+    }
+
+    if (processFrames.isEmpty()) {
+        completionHandler({ });
