+    const i32Cases = [0, 1, 2, 3, 7, 8, 9, -1, -2, -3, -7, -8, -9, 100, -100, 0x7fffffff, -0x80000000];
+    const i64Cases = [0n, 1n, 2n, 7n, 8n, 9n, -1n, -2n, -7n, -8n, -9n, 100n, -100n, (1n << 62n), -(1n << 62n), -(1n << 63n)];
