+    // Site 2: warm with sync iterables (profiles AsyncFromSync only) so the DFG compiles Check(OtherUse); then
+    // feed a genuine async iterable -> @@asyncIterator present -> OtherUse deopts -> baseline drives it.
+    for (let i = 0; i < N; i++)
