+noInline(bitAnd);
+function plusOne(s, i) { return s.charCodeAt(i) + 1; }
+noInline(plusOne);
+function isSlash(s, i) { return s.charCodeAt(i) === 47; }
+noInline(isSlash);
+function isNaNResult(s, i) { return Number.isNaN(s.charCodeAt(i)); }
+noInline(isNaNResult);
