+
+function step() {
+    // Anchored ^ non-sticky exec: match must start at 0, so input[0] gates it.
+    shouldBe(execStr(/^foo/, "foobar"), '["foo"]@0');
+    shouldBe(execStr(/^foo/, "xfoobar"), "null");        // filtered (x != f)
