+    // character class under /iu, so its ASCII partner must be in the bitmap and NOT fast-failed.
+    shouldBe(execStr(/^K/iu, "k"), '["k"]@0');
+    shouldBe(execStr(/^K/iu, "K"), '["K"]@0');
+    shouldBe(execStr(/^K/iu, "x"), "null");
