+{
+    JSGlobalObject* globalObject = nullptr;
+    RegExp* regExp = nullptr;
+    if (RegExpObject* regExpObject = node->dynamicCastConstant<RegExpObject*>()) {
+        globalObject = regExpObject->realm();
+        regExp = regExpObject->regExp();
