+        break;
+    case FirstCharacterFilterPosition::AtLastIndex:
+        if (!regExp->sticky())
+            return nullptr;
+        break;
+    }
+
+    if (globalObject->isRegExpRecompiled())
+        return nullptr;
+
+    const WTF::BitSet<256>* bitmap = regExpFirstCharacterBitmap(regExp, position);
+    if (!bitmap)
