+    Object.defineProperty(iterator, Symbol.iterator, { value: () => [42][Symbol.iterator]() });
+    shouldBeArray(Array.from(iterator), [42]);
+}
+{
+    const iterator = new Set([1, 3]).values();
+    Object.defineProperty(iterator, Symbol.iterator, { value: () => [42][Symbol.iterator]() });
+    shouldBeArray(Array.from(iterator), [42]);
