+
+        for (let i = 0; i < wasmTestLoopCount; ++i) {
+            instance.exports.copy(dstNum(3), srcNum(1), lengthNum(1));
+            assert.eq(instance.exports.callDst(dstNum(3)), 42);
+        }
+    }
+}

