+    elems += ` $f${i}`;
+    body += `        (call $import)\n        (drop (table.get $t (i32.const ${i})))\n`;
+}
+
+let wat = `
+(module
+    (import "m" "f" (func $import))
+    (table $t ${numFuncs} funcref)
+    (elem (i32.const 0)${elems})
+${funcs}    (func (export "test")
+${body}    )
+)
+`;
+
+let calls = 0;
+const imports = { m: { f: () => { ++calls; } } };
